<script>
document.querySelectorAll('[data-proc-report-tab]').forEach((tab) => tab.addEventListener('click', () => {
    document.querySelectorAll('[data-proc-report-tab]').forEach((button) => { button.classList.remove('active'); button.setAttribute('aria-selected', 'false'); });
    document.querySelectorAll('[data-proc-report-panel]').forEach((panel) => { panel.hidden = true; });
    tab.classList.add('active'); tab.setAttribute('aria-selected', 'true');
    document.querySelector(`[data-proc-report-panel="${tab.dataset.procReportTab}"]`).hidden = false;
}));
document.getElementById('period')?.addEventListener('change', (event) => {
    const custom = event.target.value === 'custom';
    document.getElementById('from').disabled = !custom;
    document.getElementById('to').disabled = !custom;
    if (!custom) event.target.form.requestSubmit();
});
</script>
